import java.util.*;

public class Main {
    // Kth largest with a min-heap of size k, tracing heap state
    static int kthLargest(int[] nums, int k, boolean trace) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int x : nums) {
            String action;
            if (heap.size() < k) {
                heap.offer(x);
                action = "push";
            } else if (x > heap.peek()) {
                int out = heap.poll();
                heap.offer(x);
                action = "replace " + out;
            } else {
                action = "skip";
            }
            if (trace) System.out.println("x=" + x + " " + action + " heap=" + heap);
        }
        return heap.peek();
    }

    static int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) freq.merge(x, 1, Integer::sum);
        PriorityQueue<Map.Entry<Integer, Integer>> heap =
            new PriorityQueue<>(Comparator.comparingInt(Map.Entry::getValue));
        for (var e : freq.entrySet()) {
            heap.offer(e);
            if (heap.size() > k) heap.poll();
        }
        int[] res = new int[k];
        for (int i = k - 1; i >= 0; i--) res[i] = heap.poll().getKey();
        return res;
    }

    static int[][] kClosest(int[][] pts, int k) {
        // max-heap on squared distance, keep k smallest
        PriorityQueue<int[]> heap = new PriorityQueue<>(
            (a, b) -> Integer.compare(b[0] * b[0] + b[1] * b[1], a[0] * a[0] + a[1] * a[1]));
        for (int[] p : pts) {
            heap.offer(p);
            if (heap.size() > k) heap.poll();
        }
        return heap.toArray(new int[0][]);
    }

    static class ListNode {
        int val; ListNode next;
        ListNode(int v) { val = v; }
    }

    static ListNode build(int... vals) {
        ListNode dummy = new ListNode(0), cur = dummy;
        for (int v : vals) { cur.next = new ListNode(v); cur = cur.next; }
        return dummy.next;
    }

    static String show(ListNode n) {
        StringBuilder sb = new StringBuilder();
        for (; n != null; n = n.next) sb.append(n.val).append(n.next != null ? "->" : "");
        return sb.toString();
    }

    static ListNode mergeK(ListNode[] lists) {
        PriorityQueue<ListNode> heap = new PriorityQueue<>(Comparator.comparingInt(n -> n.val));
        for (ListNode l : lists) if (l != null) heap.offer(l);
        ListNode dummy = new ListNode(0), tail = dummy;
        while (!heap.isEmpty()) {
            ListNode n = heap.poll();
            tail.next = n; tail = n;
            if (n.next != null) heap.offer(n.next);
        }
        return dummy.next;
    }

    static int leastInterval(char[] tasks, int n) {
        int[] cnt = new int[26];
        for (char c : tasks) cnt[c - 'A']++;
        int max = 0;
        for (int c : cnt) max = Math.max(max, c);
        int numMax = 0;
        for (int c : cnt) if (c == max) numMax++;
        return Math.max(tasks.length, (max - 1) * (n + 1) + numMax);
    }

    static class MedianFinder {
        private final PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder());
        private final PriorityQueue<Integer> high = new PriorityQueue<>();
        void addNum(int x) {
            low.offer(x);
            high.offer(low.poll());
            if (high.size() > low.size()) low.offer(high.poll());
        }
        double findMedian() {
            return low.size() > high.size() ? low.peek() : (low.peek() + high.peek()) / 2.0;
        }
        String state() { return "low=" + low + " high=" + high; }
    }

    public static void main(String[] args) {
        int[] a = {3, 2, 1, 5, 6, 4};
        System.out.println("kth largest (k=2): " + kthLargest(a, 2, true));
        int[] top = topKFrequent(new int[]{1, 1, 1, 2, 2, 3}, 2);
        System.out.println("top 2 frequent: " + Arrays.toString(top));
        int[][] pts = {{1, 3}, {-2, 2}, {5, 8}, {0, 1}};
        System.out.println("2 closest: " + Arrays.deepToString(kClosest(pts, 2)));
        ListNode merged = mergeK(new ListNode[]{build(1, 4, 5), build(1, 3, 4), build(2, 6)});
        System.out.println("merged: " + show(merged));
        System.out.println("task scheduler: "
            + leastInterval("AAABBB".toCharArray(), 2) + " "
            + leastInterval("AAAAAABCDEFG".toCharArray(), 2));
        MedianFinder mf = new MedianFinder();
        for (int x : new int[]{5, 15, 1, 3}) {
            mf.addNum(x);
            System.out.println("add " + x + " " + mf.state() + " median=" + mf.findMedian());
        }
        // mechanics
        PriorityQueue<Integer> pq = new PriorityQueue<>(List.of(9, 4, 7, 1, 8, 2));
        System.out.println("array order: " + pq + " peek=" + pq.peek());
        StringBuilder sb = new StringBuilder();
        while (!pq.isEmpty()) sb.append(pq.poll()).append(' ');
        System.out.println("poll order: " + sb.toString().trim());
        int x = Integer.MIN_VALUE, y = 5;
        System.out.println("x - y > 0 ? " + (x - y > 0));
        System.out.println("compare says x < y ? " + (Integer.compare(x, y) < 0));
    }
}

