import java.util.*;

public class Main {
    static List<List<Integer>> buildGraph(int n, int[][] edges, boolean directed) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            if (!directed) g.get(e[1]).add(e[0]);
        }
        return g;
    }

    static void dfs(List<List<Integer>> g, int u, boolean[] seen, List<Integer> order) {
        seen[u] = true;
        order.add(u);
        for (int v : g.get(u)) if (!seen[v]) dfs(g, v, seen, order);
    }

    static int components(List<List<Integer>> g) {
        boolean[] seen = new boolean[g.size()];
        int count = 0;
        for (int s = 0; s < g.size(); s++) {
            if (!seen[s]) { count++; dfs(g, s, seen, new ArrayList<>()); }
        }
        return count;
    }

    static int[] bfsDist(List<List<Integer>> g, int src, boolean trace) {
        int[] dist = new int[g.size()];
        Arrays.fill(dist, -1);
        Deque<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.offer(src);
        int step = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            List<Integer> added = new ArrayList<>();
            for (int v : g.get(u)) {
                if (dist[v] == -1) { dist[v] = dist[u] + 1; q.offer(v); added.add(v); }
            }
            if (trace) System.out.println(++step + ": pop " + u + " add " + added + " queue=" + q
                + " dist=" + Arrays.toString(dist));
        }
        return dist;
    }

    static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    static int numIslands(char[][] grid) {
        int rows = grid.length, cols = grid[0].length, count = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (grid[r][c] == '1') { count++; sink(grid, r, c); }
        return count;
    }

    static void sink(char[][] grid, int r, int c) {
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length || grid[r][c] != '1') return;
        grid[r][c] = '0';
        for (int[] d : DIRS) sink(grid, r + d[0], c + d[1]);
    }

    static int orangesRotting(int[][] grid, boolean trace) {
        int rows = grid.length, cols = grid[0].length, fresh = 0;
        Deque<int[]> q = new ArrayDeque<>();
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 2) q.offer(new int[]{r, c});
                else if (grid[r][c] == 1) fresh++;
            }
        int minutes = 0;
        while (!q.isEmpty() && fresh > 0) {
            int size = q.size();
            for (int i = 0; i < size; i++) {
            int[] cur = q.poll();
            for (int[] d : DIRS) {
                int nr = cur[0] + d[0], nc = cur[1] + d[1];
                if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || grid[nr][nc] != 1) continue;
                grid[nr][nc] = 2;
                fresh--;
                q.offer(new int[]{nr, nc});
            }
        }
        minutes++;
        if (trace) System.out.println("minute " + minutes + ": fresh left=" + fresh
            + " frontier=" + q.size());
    }
    return fresh == 0 ? minutes : -1;
}

static boolean isBipartite(int[][] graph) {
    int n = graph.length;
    int[] color = new int[n]; // 0 = unvisited, 1 and -1 are the two sides
    for (int s = 0; s < n; s++) {
        if (color[s] != 0) continue;
        Deque<Integer> q = new ArrayDeque<>();
        q.offer(s);
        color[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (color[v] == 0) { color[v] = -color[u]; q.offer(v); }
                else if (color[v] == color[u]) return false;
            }
        }
    }
    return true;
}

static int ladderLength(String begin, String end, List<String> words) {
    Set<String> dict = new HashSet<>(words);
    if (!dict.contains(end)) return 0;
    Deque<String> q = new ArrayDeque<>();
    q.offer(begin);
    Set<String> seen = new HashSet<>(List.of(begin));
    int steps = 1;
    while (!q.isEmpty()) {
        for (int i = q.size(); i > 0; i--) {
            String w = q.poll();
            if (w.equals(end)) return steps;
            char[] cs = w.toCharArray();
            for (int p = 0; p < cs.length; p++) {
                char orig = cs[p];
                for (char ch = 'a'; ch <= 'z'; ch++) {
                    cs[p] = ch;
                    String next = new String(cs);
                    if (dict.contains(next) && seen.add(next)) q.offer(next);
                }
                cs[p] = orig;
            }
        }
        steps++;
    }
    return 0;
}

