static Node cloneGraph(Node start) {
    if (start == null) return null;
    Map<Node, Node> copy = new HashMap<>();
    Deque<Node> q = new ArrayDeque<>();
    copy.put(start, new Node(start.val));
    q.offer(start);
    while (!q.isEmpty()) {
        Node u = q.poll();
            for (Node v : u.neighbors) {
                if (!copy.containsKey(v)) { copy.put(v, new Node(v.val)); q.offer(v); }
                copy.get(u).neighbors.add(copy.get(v));
            }
        }
        return copy.get(start);
    }

    public static void main(String[] args) {
        int[][] edges = {{0, 1}, {0, 2}, {1, 3}, {2, 3}, {3, 4}, {5, 6}};
        var g = buildGraph(7, edges, false);
        System.out.println("adjacency list: " + g);
        List<Integer> order = new ArrayList<>();
        dfs(g, 0, new boolean[7], order);
        System.out.println("dfs order from 0: " + order);
        System.out.println("components: " + components(g));
        System.out.println("--- BFS from 0 ---");
        int[] dist = bfsDist(g, 0, true);
        System.out.println("final dist: " + Arrays.toString(dist));

        char[][] grid = {
            "11000".toCharArray(),
            "11000".toCharArray(),
            "00100".toCharArray(),
            "00011".toCharArray()};
        System.out.println("islands: " + numIslands(grid));

        int[][] oranges = {{2, 1, 1}, {1, 1, 0}, {0, 1, 1}};
        System.out.println("rotting minutes: " + orangesRotting(oranges, true));
        int[][] stuck = {{2, 1, 1}, {0, 1, 1}, {1, 0, 1}};
        System.out.println("blocked: " + orangesRotting(stuck, false));

        System.out.println("bipartite square: "
            + isBipartite(new int[][]{{1, 3}, {0, 2}, {1, 3}, {0, 2}}));
        System.out.println("bipartite triangle: "
            + isBipartite(new int[][]{{1, 2}, {0, 2}, {0, 1}}));
        System.out.println("ladder: " + ladderLength("hit", "cog",
            List.of("hot", "dot", "dog", "lot", "log", "cog")));

        Node a = new Node(1), b = new Node(2), c = new Node(3);
        a.neighbors.addAll(List.of(b, c));
        b.neighbors.addAll(List.of(a, c));
        c.neighbors.addAll(List.of(a, b));
        Node ca = cloneGraph(a);
        System.out.println("clone: " + (ca != a) + " val=" + ca.val + " nbrs="
            + ca.neighbors.stream().map(n -> n.val).toList());
    }
}

