import java.util.*;

public class Main {
    // Kahn's algorithm. Edge {a, b} means a must come before b.
    static int[] kahn(int n, int[][] edges, boolean trace) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] e : edges) { g.get(e[0]).add(e[1]); indeg[e[1]]++; }
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q.offer(i);
        if (trace) System.out.println("start indeg=" + Arrays.toString(indeg) + " queue=" + q);
        int[] order = new int[n];
        int k = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            order[k++] = u;
            for (int v : g.get(u)) if (--indeg[v] == 0) q.offer(v);
            if (trace) System.out.println("pop " + u + " indeg=" + Arrays.toString(indeg)
                + " queue=" + q);
        }
        return k == n ? order : new int[0];   // empty array = cycle
    }

    // DFS version: 0 = new, 1 = on current path, 2 = finished
    static int[] state;
    static Deque<Integer> post;

    static boolean dfs(List<List<Integer>> g, int u) {
        state[u] = 1;
        for (int v : g.get(u)) {
            if (state[v] == 1) return false;                  // back edge: cycle
            if (state[v] == 0 && !dfs(g, v)) return false;
        }
        state[u] = 2;
        post.push(u);                                         // push after all descendants
        return true;
    }

    static int[] dfsOrder(int n, int[][] edges) {
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) g.get(e[0]).add(e[1]);
        state = new int[n];
        post = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (state[i] == 0 && !dfs(g, i)) return new int[0];
        return post.stream().mapToInt(Integer::intValue).toArray();
    }

    // LeetCode 210 wants prerequisites[i] = {course, prereq}
    static int[] findOrder(int numCourses, int[][] prerequisites) {
        int[][] edges = new int[prerequisites.length][];
        for (int i = 0; i < edges.length; i++)
            edges[i] = new int[]{prerequisites[i][1], prerequisites[i][0]};
        return kahn(numCourses, edges, false);
    }

    static String alienOrder(String[] words) {
        Map<Character, Set<Character>> g = new LinkedHashMap<>();
        Map<Character, Integer> indeg = new LinkedHashMap<>();
        for (String w : words) for (char c : w.toCharArray()) {
            g.putIfAbsent(c, new LinkedHashSet<>());
            indeg.putIfAbsent(c, 0);
        }
        for (int i = 0; i + 1 < words.length; i++) {
            String a = words[i], b = words[i + 1];
            if (a.length() > b.length() && a.startsWith(b)) return "";   // "abc" before "ab"
            for (int j = 0; j < Math.min(a.length(), b.length()); j++) {
                char x = a.charAt(j), y = b.charAt(j);
                if (x != y) {
                    if (g.get(x).add(y)) indeg.merge(y, 1, Integer::sum);
                    break;
                }
            }
        }
        Deque<Character> q = new ArrayDeque<>();
        indeg.forEach((c, d) -> { if (d == 0) q.offer(c); });
        StringBuilder sb = new StringBuilder();
        while (!q.isEmpty()) {
            char c = q.poll();
            sb.append(c);
            for (char nxt : g.get(c)) if (indeg.merge(nxt, -1, Integer::sum) == 0) q.offer(nxt);
        }
        return sb.length() == indeg.size() ? sb.toString() : "";
    }

    static boolean canFinish(int n, int[][] prereq) {
        return findOrder(n, prereq).length == n;
    }

    public static void main(String[] args) {
        // build-order style graph: 6 nodes
        int[][] edges = {{5, 2}, {5, 0}, {4, 0}, {4, 1}, {2, 3}, {3, 1}};
        System.out.println("--- Kahn ---");
        int[] order = kahn(6, edges, true);
        System.out.println("order: " + Arrays.toString(order));
        System.out.println("dfs order: " + Arrays.toString(dfsOrder(6, edges)));
        int[][] ring = {{0, 1}, {1, 2}, {2, 0}};
        System.out.println("cycle (kahn): " + Arrays.toString(kahn(3, ring, false)));
        System.out.println("cycle (dfs): " + Arrays.toString(dfsOrder(3, ring)));
        System.out.println("canFinish 2, [[1,0]]: " + canFinish(2, new int[][]{{1, 0}}));
        int[][] loop2 = {{1, 0}, {0, 1}};
        System.out.println("canFinish 2, [[1,0],[0,1]]: " + canFinish(2, loop2));
        System.out.println("findOrder 4: " + Arrays.toString(
            findOrder(4, new int[][]{{1, 0}, {2, 0}, {3, 1}, {3, 2}})));
        System.out.println("alien: " + alienOrder(new String[]{"wrt", "wrf", "er", "ett", "rftt"}));
        System.out.println("alien invalid: '" + alienOrder(new String[]{"abc", "ab"}) + "'");
    }
}

class DSU {
    final int[] parent, rank;
    int sets;                                    // number of groups
    DSU(int n) {
        parent = new int[n]; rank = new int[n]; sets = n;
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];       // path halving
            x = parent[x];
        }
        return x;
    }
    boolean union(int a, int b) {                // false if already in the same group
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;
        sets--;
        return true;
    }
}

import java.util.*;

public class Main {
    static class DSU {
        final int[] parent, rank;
        int sets;
        DSU(int n) {
            parent = new int[n]; rank = new int[n]; sets = n;
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];   // path halving
                x = parent[x];
            }
            return x;
        }
        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;
            if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) rank[ra]++;
            sets--;
            return true;
        }
    }

    static int[] redundant(int[][] edges, boolean trace) {
        DSU dsu = new DSU(edges.length + 1);
        for (int[] e : edges) {
            boolean merged = dsu.union(e[0], e[1]);
            if (trace) System.out.println("union(" + e[0] + "," + e[1] + ") merged=" + merged
                + " parent=" + Arrays.toString(dsu.parent) + " rank=" + Arrays.toString(dsu.rank));
            if (!merged) return e;
        }
        return new int[0];
    }
    static int provinces(int[][] isConnected) {
        int n = isConnected.length;
        DSU dsu = new DSU(n);
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (isConnected[i][j] == 1) dsu.union(i, j);
        return dsu.sets;
    }

    static List<List<String>> accountsMerge(List<List<String>> accounts) {
        DSU dsu = new DSU(accounts.size());
        Map<String, Integer> owner = new HashMap<>();
        for (int i = 0; i < accounts.size(); i++) {
            for (String email : accounts.get(i).subList(1, accounts.get(i).size())) {
                Integer prev = owner.putIfAbsent(email, i);
                if (prev != null) dsu.union(prev, i);
            }
        }
        Map<Integer, TreeSet<String>> groups = new TreeMap<>();
        for (var e : owner.entrySet())
            groups.computeIfAbsent(dsu.find(e.getValue()), k -> new TreeSet<>()).add(e.getKey());
        List<List<String>> res = new ArrayList<>();
        for (var g : groups.entrySet()) {
            List<String> row = new ArrayList<>();
            row.add(accounts.get(g.getKey()).get(0));
            row.addAll(g.getValue());
            res.add(row);
        }
        return res;
    }

    // Kruskal: sort edges {u, v, w} by weight, take an edge if it joins two components
    static int kruskal(int n, int[][] edges, boolean trace) {
        int[][] sorted = edges.clone();
        Arrays.sort(sorted, Comparator.comparingInt(e -> e[2]));
        DSU dsu = new DSU(n);
        int total = 0, used = 0;
        for (int[] e : sorted) {
            boolean take = dsu.union(e[0], e[1]);
            if (trace) System.out.println("edge " + e[0] + "-" + e[1] + " w=" + e[2]
                + (take ? " take" : " skip (cycle)"));
            if (take) { total += e[2]; used++; }
        }
        return used == n - 1 ? total : -1;
    }

    public static void main(String[] args) {
        System.out.println("--- redundant connection ---");
        System.out.println("answer: " + Arrays.toString(
            redundant(new int[][]{{1, 2}, {1, 3}, {2, 3}}, true)));
