import java.util.*;

public class Main {
    static final int INF = Integer.MAX_VALUE / 2;

    // edges {u, v, w}, directed
    static int[] dijkstra(int n, int[][] edges, int src, boolean trace) {
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) g.get(e[0]).add(new int[]{e[1], e[2]});
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[1], b[1]));
        pq.offer(new int[]{src, 0});
        int step = 0;
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int u = top[0], d = top[1];
            if (d > dist[u]) {
                if (trace) System.out.println(++step + ": pop (" + u + "," + d + ") stale, skip");
                continue;
            }
            for (int[] e : g.get(u)) {
                if (d + e[1] < dist[e[0]]) {
                    dist[e[0]] = d + e[1];
                    pq.offer(new int[]{e[0], dist[e[0]]});
                }
            }
            if (trace) System.out.println(++step + ": pop (" + u + "," + d + ") dist="
                + Arrays.toString(dist).replace("" + INF, "inf") + " pq size=" + pq.size());
        }
        return dist;
    }

    static int networkDelay(int[][] times, int n, int k) {
        int[] dist = dijkstra(n + 1, times, k, false);
        int max = 0;
        for (int i = 1; i <= n; i++) max = Math.max(max, dist[i]);
        return max >= INF ? -1 : max;
    }

    // Bellman-Ford limited to k+1 edges
    static int cheapest(int n, int[][] flights, int src, int dst, int k, boolean trace) {
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        for (int round = 0; round <= k; round++) {
            int[] next = dist.clone();                 // read old, write new
            for (int[] f : flights)
                if (dist[f[0]] < INF && dist[f[0]] + f[2] < next[f[1]])
                    next[f[1]] = dist[f[0]] + f[2];
            dist = next;
            if (trace) System.out.println("after " + (round + 1) + " edge(s): "
                + Arrays.toString(dist).replace("" + INF, "inf"));
        }
        return dist[dst] >= INF ? -1 : dist[dst];
    }

    static int minEffort(int[][] h) {
        int rows = h.length, cols = h[0].length;
        int[][] best = new int[rows][cols];
        for (int[] row : best) Arrays.fill(row, INF);
    best[0][0] = 0;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
    pq.offer(new int[]{0, 0, 0});
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!pq.isEmpty()) {
        int[] t = pq.poll();
        int e = t[0], r = t[1], c = t[2];
        if (e > best[r][c]) continue;
        if (r == rows - 1 && c == cols - 1) return e;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
            int ne = Math.max(e, Math.abs(h[nr][nc] - h[r][c]));   // path cost is a MAX
            if (ne < best[nr][nc]) { best[nr][nc] = ne; pq.offer(new int[]{ne, nr, nc}); }
        }
    }
    return 0;
}

// 0-1 BFS: grid cell 1 = obstacle (cost 1), 0 = free (cost 0)
static int minObstacles(int[][] grid) {
    int rows = grid.length, cols = grid[0].length;
    int[][] dist = new int[rows][cols];
    for (int[] row : dist) Arrays.fill(row, INF);
    Deque<int[]> dq = new ArrayDeque<>();
    dist[0][0] = 0;
    dq.offerFirst(new int[]{0, 0});
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!dq.isEmpty()) {
        int[] cur = dq.pollFirst();
        for (int[] d : dirs) {
            int nr = cur[0] + d[0], nc = cur[1] + d[1];
            if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
            int w = grid[nr][nc];
            if (dist[cur[0]][cur[1]] + w < dist[nr][nc]) {
                dist[nr][nc] = dist[cur[0]][cur[1]] + w;
                int[] cell = {nr, nc};
                if (w == 0) dq.offerFirst(cell); else dq.offerLast(cell);
            }
        }
    }
    return dist[rows - 1][cols - 1];
}

static int[][] floyd(int n, int[][] edges) {
    int[][] d = new int[n][n];
    for (int[] row : d) Arrays.fill(row, INF);
    for (int i = 0; i < n; i++) d[i][i] = 0;
    for (int[] e : edges) d[e[0]][e[1]] = Math.min(d[e[0]][e[1]], e[2]);
    for (int k = 0; k < n; k++)               // intermediate vertex MUST be the outer loop
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];
    return d;
}

